import sys, ezdxf
from collections import Counter
f = sys.argv[1]
d = ezdxf.readfile(f)
msp = d.modelspace()
print('units', d.header.get('$INSUNITS'), 'layers', [l.dxf.name for l in d.layers])
print(Counter((e.dxftype(), e.dxf.layer) for e in msp))
print('blocks', [b.name for b in d.blocks])
def show(e, pre=''):
    t = e.dxftype()
    if t == 'LINE':
        print(pre, 'LINE', e.dxf.layer, tuple(round(v, 3) for v in e.dxf.start[:2]), tuple(round(v, 3) for v in e.dxf.end[:2]), e.dxf.linetype)
    elif t == 'ARC':
        print(pre, 'ARC', e.dxf.layer, tuple(round(v, 3) for v in e.dxf.center[:2]), round(e.dxf.radius, 3), round(e.dxf.start_angle, 2), round(e.dxf.end_angle, 2))
    elif t == 'CIRCLE':
        print(pre, 'CIRCLE', e.dxf.layer, tuple(round(v, 3) for v in e.dxf.center[:2]), round(e.dxf.radius, 3))
    elif t == 'LWPOLYLINE':
        print(pre, 'LWPOLY', e.dxf.layer, [(round(p[0], 3), round(p[1], 3), round(p[4], 3)) for p in e.get_points()], e.closed)
    elif t == 'INSERT':
        print(pre, 'INSERT', e.dxf.name, e.dxf.insert, e.dxf.xscale)
    elif t in ('TEXT', 'MTEXT'):
        print(pre, t, e.dxf.layer, getattr(e.dxf, 'text', ''), e.dxf.insert)
    elif t == 'DIMENSION':
        print(pre, 'DIM', e.dxf.layer, e.dxf.text, getattr(e.dxf, 'actual_measurement', None))
    else:
        print(pre, t, e.dxf.layer)
for e in msp:
    show(e)
for b in d.blocks:
    if b.name.startswith('*'): continue
    print('BLOCK', b.name)
    for e in b:
        show(e, '  ')

