import ezdxf, sys, os, math
f = sys.argv[1]
S = 5.0
d = ezdxf.readfile(os.path.join(r'C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\12-11-2026\521112-02', f))
ms = d.modelspace()
lines = set()
for e in ms:
    if e.dxftype() == 'LINE' and e.dxf.layer != '_0-0_0' and e.dxf.color == 222:
        a = (round(e.dxf.start.x, 3), round(e.dxf.start.y, 3)); b = (round(e.dxf.end.x, 3), round(e.dxf.end.y, 3))
        lines.add(tuple(sorted([a, b])))
lines = list(lines)
# connected components
parent = list(range(len(lines)))
def find(i):
    while parent[i] != i:
        parent[i] = parent[parent[i]]; i = parent[i]
    return i
pts = {}
for i, (a, b) in enumerate(lines):
    for p in (a, b):
        if p in pts: parent[find(i)] = find(pts[p])
        else: pts[p] = i
comps = {}
for i in range(len(lines)): comps.setdefault(find(i), []).append(lines[i])
def bb(c):
    xs = [p[0] for l in c for p in l]; ys = [p[1] for l in c for p in l]
    return min(xs), min(ys), max(xs), max(ys)
best = max(comps.values(), key=lambda c: (bb(c)[2] - bb(c)[0]) * (bb(c)[3] - bb(c)[1]))
for c in comps.values():
    b = bb(c); print('comp', len(c), [round(v, 2) for v in b], 'size', round((b[2] - b[0]) * S, 2), round((b[3] - b[1]) * S, 2))
x0, y0, x1, y1 = bb(best)
print('OUTLINE bbox real', round((x1 - x0) * S, 3), round((y1 - y0) * S, 3), 'n', len(best))
# order the outline
adj = {}
for a, b in best:
    adj.setdefault(a, []).append(b); adj.setdefault(b, []).append(a)
start = min(adj, key=lambda p: (p[1], p[0]))
path = [start]; prev = None; cur = start
while True:
    nxt = [q for q in adj[cur] if q != prev]
    if not nxt: break
    n = nxt[0]
    if n == start: break
    path.append(n); prev, cur = cur, n
print('path len', len(path))
print('OUTLINE (local mm, x right, y up):')
for p in path: print('  (%.3f, %.3f)' % ((p[0] - x0) * S, (p[1] - y0) * S))
circ = {}
for e in ms:
    if e.dxftype() == 'CIRCLE' and e.dxf.layer != '_0-0_0':
        cx, cy = e.dxf.center.x, e.dxf.center.y
        if x0 - 1 <= cx <= x1 + 1 and y0 - 1 <= cy <= y1 + 1:
            circ.setdefault((round((cx - x0) * S, 2), round((cy - y0) * S, 2)), set()).add(round(e.dxf.radius * 2 * S, 2))
print('CIRCLES local mm:')
for k in sorted(circ, key=lambda k: (k[1], k[0])): print('  ', k, sorted(circ[k]))
pt = set()
for e in ms:
    if e.dxftype() == 'POINT' and e.dxf.layer != '_0-0_0':
        px, py = e.dxf.location.x, e.dxf.location.y
        if x0 - 1 <= px <= x1 + 1 and y0 - 1 <= py <= y1 + 1: pt.add((round((px - x0) * S, 2), round((py - y0) * S, 2)))
print('POINTS:', sorted(pt))

